package com.snipify.handler;
import com.amazonaws.services.lambda.runtime.*;import com.amazonaws.services.lambda.runtime.events.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.snipify.cache.RedisCache;import com.snipify.model.*;import com.snipify.repository.UrlRepository;import com.snipify.util.*;import software.amazon.awssdk.services.dynamodb.DynamoDbClient;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.Map;
public class CreateUrlHandler implements RequestHandler<APIGatewayV2HTTPEvent,APIGatewayV2HTTPResponse>{
 private static final ObjectMapper JSON=new ObjectMapper();private static final UrlRepository REPO=new UrlRepository(DynamoDbClient.create(),env("TABLE_NAME"));private static final RedisCache CACHE=new RedisCache(env("REDIS_HOST"),Integer.parseInt(env("REDIS_PORT")),Integer.parseInt(env("CACHE_TTL_SECONDS")));private static final String BASE=env("BASE_URL");
 public APIGatewayV2HTTPResponse handleRequest(APIGatewayV2HTTPEvent e,Context c){try{var q=JSON.readValue(e.getBody(),CreateUrlRequest.class);if(!UrlValidator.isValid(q.originalUrl()))return ApiResponses.json(400,"{\"message\":\"A valid HTTP or HTTPS URL is required\"}");int days=q.expiryDays()==null?30:q.expiryDays();if(days<1||days>365)return ApiResponses.json(400,"{\"message\":\"expiryDays must be between 1 and 365\"}");Instant now=Instant.now();for(int x=0;x<5;x++){String code=ShortCodeGenerator.generate();var m=new UrlMapping(code,q.originalUrl().trim(),now.toString(),now.plus(days,ChronoUnit.DAYS).getEpochSecond(),"ACTIVE");if(REPO.create(m)){try{CACHE.put(m);}catch(Exception ce){c.getLogger().log("Cache warm skipped: "+ce.getMessage());}return ApiResponses.json(201,JSON.writeValueAsString(Map.of("shortCode",code,"shortUrl",BASE+"/"+code,"originalUrl",m.originalUrl(),"expiresAt",m.expiresAt())));}}return ApiResponses.json(503,"{\"message\":\"Unique code unavailable\"}");}catch(Exception x){c.getLogger().log("Create failed: "+x);return ApiResponses.json(500,"{\"message\":\"Internal server error\"}");}}
 private static String env(String n){String v=System.getenv(n);if(v==null||v.isBlank())throw new IllegalStateException(n+" required");return v;}
}
